const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'P(-2,-3)' },
      { kind: 'text', payload: '第三象限' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var ox = Math.round(W * 0.58);
    var oy = Math.round(H * 0.36);
    var u = Math.min(W / 11, H / 10);
    var px = ox - 2 * u;
    var py = oy + 3 * u;
    var left = Math.round(W * 0.06);
    var right = Math.round(W * 0.95);
    var top = Math.round(H * 0.06);
    var bottom = Math.round(H * 0.94);
    var r = Math.max(3, u * 0.18);

    var xAxis = visualSdk.axis({ x0: left, y0: oy, x1: right, y1: oy, ticks: 8, tickLength: 6 });
    var yAxis = visualSdk.axis({ x0: ox, y0: bottom, x1: ox, y1: top, ticks: 8, tickLength: 6 });
    var dashH = [['M', px, py], ['L', ox, py]];
    var dashV = [['M', px, py], ['L', px, oy]];
    var dot = visualSdk.circle(px, py, r);

    return {
      schemaVersion: 1,
      sceneId: 'point-p-quadrant3',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xAxis', commands: xAxis },
        { id: 'yAxis', commands: yAxis },
        { id: 'dashH', commands: dashH },
        { id: 'dashV', commands: dashV },
        { id: 'dot', commands: dot }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'xAxis', fill: '#26354a', stroke: { width: 2, cap: 'butt', join: 'miter' } },
        { type: 'path', pathId: 'yAxis', fill: '#26354a', stroke: { width: 2, cap: 'butt', join: 'miter' } },
        { type: 'path', pathId: 'dashH', fill: '#5b6b80', stroke: { width: 2, cap: 'butt', dash: [7, 5] } },
        { type: 'path', pathId: 'dashV', fill: '#5b6b80', stroke: { width: 2, cap: 'butt', dash: [7, 5] } },
        { type: 'path', pathId: 'dot', fill: '#b83227', stroke: { width: 1 } },
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: right - 4, y: oy - 8 }, hAlign: 'right', vAlign: 'bottom', color: '#26354a' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: ox + 8, y: top + 4 }, hAlign: 'left', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: ox - 6, y: oy + 6 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: px - r - 6, y: py }, hAlign: 'right', vAlign: 'middle', color: '#b83227' },
        { type: 'label', contentId: metrics[4].contentId, anchor: { x: ox - 3.4 * u, y: oy + 4.6 * u }, hAlign: 'center', vAlign: 'middle', color: '#4a5b73' }
      ] }
    };
  }
};
